26	    public static String of(Owner owner) {
27	        String telephone = OwnerTelephones.toE164OrRaw(owner.getTelephone());
28	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
29	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
